:root {
  --paper: #fffdf8;
  --ink: #243044;
  --muted: #697386;
  --coral: #ee806b;
  --coral-pale: #ffe4dc;
  --line: #eaded4;
}

.fold-kit {
  box-sizing: border-box;
  width: 440px;
  padding: 14px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--paper);
  color: var(--ink);
}

.kit-header {
  display: flex;
  align-items: center;
  gap: 10px;
}

.mark {
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  border-radius: 13px;
  background: var(--coral-pale);
  font-size: 23px;
}

.eyebrow {
  margin: 0 0 2px;
  color: var(--coral);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1px;
}

h1 {
  margin: 0;
  font-size: 21px;
  line-height: 1;
}

.level {
  margin-left: auto;
  color: var(--muted);
  font-size: 13px;
  font-weight: 700;
}

.instructions {
  margin: 13px 0 12px;
  padding: 10px 12px;
  border-radius: 10px;
  background: var(--coral-pale);
  font-size: 14px;
  line-height: 1.35;
}

.instructions p {
  margin: 0;
}

.step {
  margin-top: 5px !important;
  color: var(--muted);
}

.step strong {
  color: var(--ink);
}

button {
  width: 100%;
  padding: 9px 12px;
  border: 0;
  border-radius: 9px;
  background: var(--coral);
  color: var(--paper);
  font-size: 14px;
  font-weight: 700;
}
